mapper.select:
SELECT combined.*, ( SELECT COUNT(*) FROM lost_comment c WHERE c.num = combined.num ) AS commentCount FROM ( /* ================= 1. 사용자 분실물 데이터 (lost) ================= */ SELECT num, atc_id, id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, prdt_category, created_at, updated_at, done, is_deleted, lst_filepath_img, view_count FROM lost WHERE is_deleted = 0
AND prdt_cl_nm IN #{item}
AND prdt_category = #{subCategory}
AND lst_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
AND lst_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')
AND done = 0 AND done = 1
AND id LIKE CONCAT('%', #{author}, '%')
AND lst_prdt_nm LIKE CONCAT('%', #{keyword}, '%')
UNION ALL
/* ================= 2. 경찰청 유실물 데이터 (lost_police) ================= */ SELECT num, atc_id, id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, prdt_category, created_at, updated_at, done, is_deleted, lst_filepath_img, view_count FROM lost_police WHERE is_deleted = 0
AND prdt_cl_nm IN #{item}
AND prdt_category = #{subCategory}
AND lst_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
AND lst_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')
AND id LIKE CONCAT('%', #{author}, '%')
AND done = 0 AND done = 1
AND lst_prdt_nm LIKE CONCAT('%', #{keyword}, '%')
) combined
ORDER BY combined.lst_ymd ASC, num ASC ORDER BY combined.lst_ymd DESC, num DESC
LIMIT #{paging.offset}, #{paging.size}

mapper.update:
UPDATE lost
SET is_deleted=1
WHERE atc_id=#{atcId}

mapper.select:
SELECT combined_lost.*, combined_lost.dataSource, f.id AS file_id, f.atc_id AS file_atc_id, f.lst_filepath_img AS lst_filepath_img, f.save_name, f.file_size, f.file_path FROM( SELECT num, atc_id, id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, prdt_category, created_at, updated_at, done, is_deleted, view_count, lst_filepath_img, 'user' AS dataSource FROM lost WHERE is_deleted=0 And atc_id = #{atcId}
UNION ALL
SELECT num, atc_id, id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, prdt_category, created_at, updated_at, done, is_deleted, view_count, lst_filepath_img, 'police' AS dataSource FROM lost_police WHERE is_deleted=0 And atc_id = #{atcId} ) combined_lost LEFT JOIN lost_file f on combined_lost.atc_id=f.atc_id

mapper.update:
UPDATE lost
SET
lst_filepath_img=#{lstFilepathImg}
WHERE atc_id = #{atcId}

mapper.select:
SELECT COUNT(*) FROM ( /* 1. 유저 데이터 개수 */ SELECT num FROM lost WHERE is_deleted = 0
AND prdt_cl_nm IN #{item}
AND prdt_category = #{subCategory} AND lst_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s') AND lst_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s') AND id LIKE CONCAT('%', #{author}, '%') AND lst_prdt_nm LIKE CONCAT('%', #{keyword}, '%')
AND done = 0 AND done = 1
UNION ALL
/* 2. 경찰청 데이터 개수 */ SELECT num FROM lost_police WHERE is_deleted = 0
AND prdt_cl_nm IN #{item}
AND prdt_category = #{subCategory} AND lst_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s') AND lst_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s') AND id LIKE CONCAT('%', #{author}, '%') AND lst_prdt_nm LIKE CONCAT('%', #{keyword}, '%')
AND done = 0 AND done = 1
) total_count
